Here's how to use MSTest's comparison assertions for your scoring system:

## Comparison Assertions

```csharp
// Assert.IsGreaterThan(lowerBound, actual) — actual must exceed lowerBound
// Assert.IsLessThan(upperBound, actual) — actual must be below upperBound
// Assert.IsInRange(actual, low, high) — actual must be within [low, high]
```

## Example Tests

```csharp
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace Contoso.Scoring.Tests;

[TestClass]
public sealed class ScoreCalculatorTests
{
    private readonly ScoreCalculator _calculator = new();

    [TestMethod]
    [DataRow(7, 10, 70.0)]
    [DataRow(10, 10, 100.0)]
    [DataRow(0, 10, 0.0)]
    public void CalculatePercentage_ValidInputs_ReturnsExpected(int correct, int total, double expected)
    {
        var result = _calculator.CalculatePercentage(correct, total);
        Assert.AreEqual(expected, result);
    }

    [TestMethod]
    public void CalculatePercentage_Result_IsInValidRange()
    {
        var result = _calculator.CalculatePercentage(3, 7);

        Assert.IsInRange(result, 0.0, 100.0);
        Assert.IsGreaterThan(0.0, result); // result > 0
    }

    [TestMethod]
    public void NormalizeScore_PartialScore_IsInRange()
    {
        var result = _calculator.NormalizeScore(45.0, 60.0);

        Assert.IsInRange(result, 0.0, 100.0);
        Assert.IsGreaterThan(0.0, result);
        Assert.IsLessThan(100.0, result);
    }

    [TestMethod]
    public void NormalizeScore_ExceedsMax_CapsAt100()
    {
        var result = _calculator.NormalizeScore(120.0, 100.0);

        Assert.AreEqual(100.0, result);
    }

    [TestMethod]
    [DataRow(95.0, "A")]
    [DataRow(85.0, "B")]
    [DataRow(75.0, "C")]
    [DataRow(65.0, "D")]
    [DataRow(50.0, "F")]
    public void GetGrade_ReturnsCorrectGrade(double percentage, string expected)
    {
        Assert.AreEqual(expected, _calculator.GetGrade(percentage));
    }

    [TestMethod]
    [DataRow(90.0)]
    [DataRow(89.999)]
    [DataRow(80.0)]
    public void GetGrade_BoundaryValues_ReturnsCorrectGrade(double percentage)
    {
        var grade = _calculator.GetGrade(percentage);
        // Grade must be a valid single-character grade
        Assert.Contains(grade, new[] { "A", "B", "C", "D", "F" });
    }

    [TestMethod]
    public void CalculatePercentage_ZeroTotal_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculatePercentage(5, 0));
    }

    [TestMethod]
    public void CalculatePercentage_NegativeCorrect_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculatePercentage(-1, 10));
    }

    [TestMethod]
    public void CalculatePercentage_CorrectExceedsTotal_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculatePercentage(11, 10));
    }
}
```

## Key Points

| Assertion | Meaning |
|-----------|---------|
| `Assert.IsGreaterThan(0.0, result)` | result > 0.0 |
| `Assert.IsLessThan(100.0, result)` | result < 100.0 |
| `Assert.IsInRange(result, 0.0, 100.0)` | 0.0 ≤ result ≤ 100.0 |

**Note:** The parameter order for `IsGreaterThan`/`IsLessThan` is `(bound, actual)` — the *actual* value is the second argument. `IsInRange` is `(actual, low, high)`.

These assertions produce much better failure messages than `Assert.IsTrue(result > 0)` — they'll show the actual value and the bound that was violated.
